import re
seq_lines=[]
with open('region.fasta') as f:
    for line in f:
        if not line.startswith('>'):
            seq_lines.append(line.strip())
seq=''.join(seq_lines).upper()
N=len(seq)
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
both={'+':seq,'-':rc(seq)}

motifs={
 'tRNA A-box':'TGGCNNAGTGG'.replace('N','[ACGT]'),
 'tRNA B-box':'GGTTCGANNCC'.replace('N','[ACGT]'),
 '-35 promoter':'TTGACA',
 '-10 promoter':'TATAAT',
 'DnaA box':'TTATCCACA',
 'CAP site':'AATGTGATCTAGATCACATTT',
 'LTR/terminator stem?':'GCGCGC',
 'purine tract (R>=12)':'[AG]{12,}',
 'pyrimidine tract (Y>=12)':'[CT]{12,}',
 'AG repeat':'[AG]{8,}',
 'CT repeat':'[CT]{8,}',
 'mono-A-exact':'A{6,}',
}
for name,pat in motifs.items():
    hits=[]
    for strand,s in both.items():
        for m in re.finditer('(?=('+pat+'))',s):
            if strand=='+': hits.append((m.start()+1,len(m.group(1)),m.group(1)))
            else: hits.append((N-m.start()-len(m.group(1))+1, len(m.group(1)), rc(m.group(1))))
    print(f'{name:22s}: n={len(hits)}', hits[:6])
